client_script:
(function () {
  "use strict";

  function fmt(emp, mode) {
    var fn = emp.first_name || "";
    var ln = emp.last_name || "";
    if (mode === "FL") {
      return fn + (ln ? " " + ln.charAt(0).toUpperCase() + "." : "");
    } else {
      return (fn ? fn.charAt(0).toUpperCase() + ". " : "") + ln;
    }
  }

  function buildSelect(employees, mode) {
    var sel = document.getElementById("lcs-emp-select");
    if (!sel) return;
    var prev = sel.value;
    sel.innerHTML = '<option value="">— select your name —</option>';
    employees.forEach(function (emp) {
      var opt = document.createElement("option");
      opt.value = emp.name;
      opt.textContent = fmt(emp, mode);
      if (emp.name === prev) opt.selected = true;
      sel.appendChild(opt);
    });
  }

  function setRawField(employeeName) {
    var rawInput = document.querySelector(
      'input[data-fieldname="custom_referring_employee"], ' +
      'input[name="custom_referring_employee"]'
    );
    if (rawInput) {
      rawInput.value = employeeName;
      rawInput.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  function injectEmployeeUI() {
    // Find the raw field wrapper by looking for its label text
    var allFormGroups = document.querySelectorAll(".form-group, .frappe-control");
    var targetWrapper = null;

    allFormGroups.forEach(function (group) {
      var label = group.querySelector("label");
      if (label && label.textContent.trim().replace("*","").trim().indexOf("Referral submitted") === 0) {
        targetWrapper = group;
      }
    });

    if (!targetWrapper) {
      setTimeout(injectEmployeeUI, 300);
      return;
    }

    // Hide the raw field visually but keep it in DOM for value binding
    targetWrapper.style.display = "none";

    // Build our custom UI
    var ui = document.createElement("div");
    ui.style.cssText = "margin-bottom:1.5rem";
    ui.innerHTML = [
      '<label style="font-weight:600;font-size:0.9rem;display:block;margin-bottom:8px;color:#333">',
      'Referral submitted for this Left Coast Employee <span style="color:#e74c3c">*</span>',
      '</label>',
      '<div style="display:flex;align-items:center;gap:16px;margin-bottom:10px;flex-wrap:wrap">',
      '<span style="font-size:0.8rem;color:#6c757d">Display format:</span>',
      '<label style="font-size:0.85rem;cursor:pointer;display:flex;align-items:center;gap:5px;font-weight:normal">',
      '<input type="radio" name="lcs_fmt" value="FL" checked>',
      'First name + last initial &nbsp;<em style="color:#999">(e.g. Lucian S.)</em>',
      '</label>',
      '<label style="font-size:0.85rem;cursor:pointer;display:flex;align-items:center;gap:5px;font-weight:normal">',
      '<input type="radio" name="lcs_fmt" value="lL">',
      'First initial + last name &nbsp;<em style="color:#999">(e.g. L. Stacy)</em>',
      '</label>',
      '</div>',
      '<select id="lcs-emp-select" ',
      'style="width:100%;max-width:400px;padding:8px 12px;',
      'border:1px solid #d1d5db;border-radius:6px;font-size:0.95rem;',
      'background:#fff;color:#333;cursor:pointer">',
      '<option value="">Loading employees...</option>',
      '</select>',
      '<div id="lcs-emp-error" ',
      'style="color:#e74c3c;font-size:0.82rem;margin-top:6px;display:none">',
      '&#9888; Please select your name before submitting.',
      '</div>',
    ].join("");

    // Insert our UI before the hidden raw field wrapper
    targetWrapper.parentNode.insertBefore(ui, targetWrapper);

    // Fetch employees
    fetch("/api/method/beveren_fsm.field_service_management.api.lead_referral.get_employee_list", {
      headers: { "X-Frappe-CSRF-Token": "fetch" }
    })
      .then(function (r) { return r.json(); })
      .then(function (data) {
        var employees = data.message || [];
        var mode = "FL";
        buildSelect(employees, mode);

        document.querySelectorAll('input[name="lcs_fmt"]').forEach(function (radio) {
          radio.addEventListener("change", function () {
            mode = this.value;
            buildSelect(employees, mode);
          });
        });

        document.getElementById("lcs-emp-select").addEventListener("change", function () {
          setRawField(this.value);
          document.getElementById("lcs-emp-error").style.display = "none";
        });
      })
      .catch(function () {
        var sel = document.getElementById("lcs-emp-select");
        if (sel) sel.innerHTML = '<option value="">Unable to load — please contact management</option>';
      });

    // Validate on submit
    var btn = document.querySelector(".btn-submit-web-form, input[type=submit], button[type=submit], .btn-primary");
    if (btn) {
      btn.addEventListener("click", function (e) {
        var sel = document.getElementById("lcs-emp-select");
        if (!sel || !sel.value) {
          e.preventDefault();
          e.stopImmediatePropagation();
          document.getElementById("lcs-emp-error").style.display = "block";
          sel && sel.scrollIntoView({ behavior: "smooth" });
          return false;
        }
      }, true);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", injectEmployeeUI);
  } else {
    setTimeout(injectEmployeeUI, 500);
  }
})();
